import Foundation
import Testing
@testable import Core

@Test func closingsExtractOnlyTheLastBoundedNonsecretSentence() {
    #expect(PersonalClosing.extract("初めです。最後です。\n") == "最後です。")
    #expect(PersonalClosing.extract("初め！末尾です") == "末尾です")
    #expect(PersonalClosing.extract("初め。最後です！？") == "最後です！？")
    #expect(PersonalClosing.extract("！？") == nil)
    #expect(PersonalClosing.extract(String(repeating: "あ", count: 41)) == nil)
    #expect(PersonalClosing.extract("a") == nil)
    #expect(PersonalClosing.extract("token=sk-dummy-test-key-not-a-real-secret-0000") == nil)
    var capture = PersonalClosing.Capture(scene: PersonalScene(app: "editor", shape: .line, mode: .new, reply: false))
    capture.append("終わり", source: 1, authored: true)
    capture.append("です。", source: 2, authored: true)
    #expect(capture.closing == "終わりです。" && capture.sources == [1, 2])
    capture.observe(left: "前文。終わりです。")
    #expect(capture.closing == "終わりです。")
    capture.observe(left: "別の文。")
    #expect(capture.closing == nil)
    capture.append("本人です。", source: 3, authored: true)
    capture.observe(left: nil, deleted: true)
    #expect(capture.closing == nil && capture.sources.isEmpty)
    capture.append("本人です。", source: 4, authored: true)
    capture.append("モデルの文", source: 5, authored: false)
    #expect(capture.closing == nil && capture.sources.isEmpty)
}

@Test @MainActor func closingsUseOpeningPrivacyAndAllStorageLifecyclesWithoutAnySuggestionPath() async throws {
    let directory = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: directory) }
    let store = try PersonalStore(url: directory.appendingPathComponent("personal.sqlite"))
    let learner = PersonalLearner(storeURL: nil); learner.attachStoreForTesting(store)
    let scene = PersonalScene(app: "editor", shape: .line, mode: .new, reply: false)
    let other = PersonalScene(app: "mail", shape: .line, mode: .new, reply: false)
    let source = try #require(learner.recordCommit(.init(scene: scene, kind: "enter", reading: nil, surface: "本人の文です。", defaultSurface: nil)))
    let model = try #require(learner.recordCommit(.init(scene: scene, kind: "ai", reading: nil, surface: "モデルの文です。", defaultSurface: nil)))
    learner.recordClosing(scene: scene, text: "本人の文です。", sources: [source])
    learner.recordClosing(scene: other, text: "本人の文です。", sources: [source])
    learner.recordClosing(scene: scene, text: "モデルの文です。", sources: [model])
    learner.recordClosing(scene: scene, text: String(repeating: "あ", count: 41), sources: [source])
    learner.recordClosing(scene: scene, text: "本人の文です。", sources: [])
    learner.recordClosing(scene: PersonalScene(app: "com.1password.1password", shape: .line, mode: .new, reply: false), text: "本人の文です。", sources: [source])
    learner.flush()
    #expect(try store.scalarInt("SELECT COUNT(*) FROM closings") == 2)
    #expect(learner.closingSummary().split(separator: "\n").count == 2)
    let reopened = try PersonalStore(url: store.url)
    #expect(try reopened.scalarInt("SELECT COUNT(*) FROM closings") == 2)
    let export = try learner.export(to: directory.appendingPathComponent("export.jsonl"))
    #expect(try String(contentsOf: export, encoding: .utf8).contains("\"table\":\"closings\""))
    let snapshot = directory.appendingPathComponent("snapshot.sqlite")
    try store.snapshot(to: snapshot)
    #expect(try LabSnapshot.readCommits(url: snapshot).count == 2)
    _ = try LabSnapshot.readUpperBoundAuxiliary(url: snapshot)
    #expect(learner.openingSuggestion(scene: scene) == nil)
    learner.forgetApp(scene.app); learner.flush()
    #expect(try store.scalarInt("SELECT COUNT(*) FROM closings") == 1)
    try store.execute("UPDATE closings SET ts=0")
    try PersonalLearner.pruneExpired(store: store, now: Date())
    #expect(try store.scalarInt("SELECT COUNT(*) FROM closings") == 0)
    try store.execute("INSERT INTO closings(ts,scene,app,text) VALUES(1,'mail|line|new|-','mail','終わり。')")
    learner.deleteAll(); learner.flush()
    #expect(try store.scalarInt("SELECT COUNT(*) FROM closings") == 0)
    try await Task.sleep(for: .milliseconds(30))
    learner.flush()
}
